Node* reverse(Node* head) {
    Node* prev = nullptr;
    Node* cur = head;
    while (cur) {
        cur->next = prev;
        prev = cur;
        cur = cur->next;
    }
    return prev;
}

class Node:
    def __init__(self, v, nxt=None):
        self.v, self.next = v, nxt

def remove_nth(head, n):
    dummy = Node(0, head)
    fast = slow = dummy
    for _ in range(n + 1):
        fast = fast.next
    while fast:
        fast, slow = fast.next, slow.next
    slow.next = slow.next.next
    return dummy.next

